@app.get("/docs/{doc_id}")
async def get_doc(doc_id: str, request: Request):
    if doc_id not in DOCS:
        return JSONResponse(status_code=404, content={"error": "Not Found"})

    resp = doc_response(doc_id)

    # Honor If-None-Match on GET as well (RFC 9110 §13.1.2): if the client's
    # cached representation is still current, reply 304 Not Modified.
    if_none_match = request.headers.get("if-none-match")
    if if_none_match:
        candidates = {t.strip().replace("W/", "") for t in if_none_match.split(",")}
        etag = resp.headers["ETag"]
        if "*" in candidates or etag in candidates:
            return Response(status_code=304, headers={"ETag": etag})

    return resp

